export fn kahn(v:[*]const i64,n:usize)i64{if(n<2 or n>258)return -2;const nv=v[0];const ne=v[1];if(nv<0 or nv>32 or ne<0 or ne>128 or n!=2+2*@as(usize,@intCast(ne)))return -2;var adj:[32][32]bool=@splat(@splat(false));var ind:[32]i64=@splat(0);var q:[32]usize=@splat(0);for(0..@as(usize,@intCast(ne)))|i|{const a=v[2+2*i];const b=v[3+2*i];if(a<0 or a>=nv or b<0 or b>=nv)return -2;const ai:usize=@intCast(a);const bi:usize=@intCast(b);if(!adj[ai][bi]){adj[ai][bi]=true;ind[bi]+=1;}}var head:usize=0;var tail:usize=0;for(0..@as(usize,@intCast(nv)))|i|{if(ind[i]==0){q[tail]=i;tail+=1;}}while(head<tail){const x=q[head];head+=1;for(0..@as(usize,@intCast(nv)))|y|{if(adj[x][y]){ind[y]-=1;if(ind[y]==0){q[tail]=y;tail+=1;}}}}if(tail==@as(usize,@intCast(nv)))return nv;return -1;}
